/* Inflate the rows once at load. */
DND.SPELLS = DND.SPELL_ROWS.map(function (r, i) {
  return {
    id: i, name: r[0], level: r[1], school: r[2],
    castingTime: r[3], range: r[4],
    v: !!r[5], s: !!r[6], m: !!r[7], material: r[8],
    duration: r[9], ritual: !!r[10], concentration: !!r[11],
    source: r[12], costly: !!r[13], consumed: !!r[14],
    components: [r[5] ? 'V' : null, r[6] ? 'S' : null, r[7] ? 'M' : null]
      .filter(Boolean).join(', ')
  };
});

DND.SPELL_BY_NAME = {};
DND.SPELLS.forEach(function (s) { DND.SPELL_BY_NAME[s.name.toLowerCase()] = s; });

DND.findSpell = function (id) { return DND.SPELLS[id] || null; };

/* Spell ids available to a class, honouring which books are switched on.
   `extra` carries subclass or feature grants that bypass the class list. */
DND.spellsForClass = function (classId, books, extra) {
  var lists = DND.SPELL_LISTS[classId] || {};
  var seen = {}, out = [];
  Object.keys(lists).forEach(function (book) {
    if (books && books[book] === false) return;
    lists[book].forEach(function (id) { if (!seen[id]) { seen[id] = 1; out.push(id); } });
  });
  (extra || []).forEach(function (id) { if (!seen[id]) { seen[id] = 1; out.push(id); } });
  return out;
};

DND.ordinal = function (n) {
  if (n === 0) return 'Cantrip';
  var s = ['th','st','nd','rd'], v = n % 100;
  return n + (s[(v - 20) % 10] || s[v] || s[0]);
};
